ALTER TABLE public.help_chat_messages ADD COLUMN sender_type text CHECK (sender_type IN ('team','organizer')), ADD COLUMN sender_user_id uuid;
GRANT INSERT ON public.help_chat_messages TO authenticated;
CREATE POLICY "Admins send team replies" ON public.help_chat_messages FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin') AND role = 'assistant' AND sender_type = 'team' AND sender_user_id = auth.uid() AND length(trim(content)) BETWEEN 1 AND 4000 AND EXISTS (SELECT 1 FROM public.org_members m WHERE m.user_id = help_chat_messages.user_id AND m.organization_id = help_chat_messages.organization_id));
CREATE POLICY "Organizers send human chat messages" ON public.help_chat_messages FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id AND sender_user_id = auth.uid() AND role = 'user' AND sender_type = 'organizer' AND needs_human = true AND length(trim(content)) BETWEEN 1 AND 4000 AND EXISTS (SELECT 1 FROM public.org_members m WHERE m.user_id = auth.uid() AND m.organization_id = help_chat_messages.organization_id));